function nearestTarget(){return enemies.filter(e=>!e.dead).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0]}
function update(dt){time+=dt;player.walk+=dt*8;player.attack=Math.max(0,player.attack-dt);player.shootCd=Math.max(0,player.shootCd-dt);player.fire=Math.max(0,player.fire-dt);player.inv=Math.max(0,player.inv-dt);player.dodge=Math.max(0,player.dodge-dt);player.stun=Math.max(0,player.stun-dt);if(player.attack===0)player.lastHit=0;
 let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(player.lock){let t=nearestTarget();if(t)player.face=Math.sign(t.x-player.x)||player.face}else if(mx)player.face=Math.sign(mx);let len=Math.hypot(mx,my)||1;if(player.stun<=0){let speed=player.dodge>0?510:player.attack>0?135:265;player.x+=mx/len*speed*dt;player.y+=my/len*speed*.52*dt;}player.x=clamp(player.x,-850,850);player.y=clamp(player.y,-130,130);if(player.vz||player.z){player.z+=player.vz;player.vz-=29*dt;if(player.z<=0){player.z=0;player.vz=0}}
 if(player.attack>0&&player.attack<.25){for(const e of enemies){if(e.dead||e.lastSwing===player.lastHit+1)continue;let dx=e.x-player.x,dy=e.y-player.y;if(Math.abs(dx)<(player.combo===3?145:108)&&Math.abs(dy)<58&&Math.sign(dx)===player.face){e.lastSwing=(player.lastHit||0)+1;e.hp-=player.combo===3?38:25;e.hit=.18;e.stun=.38;e.x+=player.face*(player.combo===3?55:32);particle(e.x,e.y,44,'#ffd77e',12,180);floatText(e.x,e.y+50,player.combo===3?'CRÍTICO':'-'+(player.combo===3?38:25));shake=5;addStyle(45+(player.combo===3?28:0));score+=25;if(e.hp<=0){e.dead=.45;kills++;score+=150;player.hp=Math.min(player.max,player.hp+5);particle(e.x,e.y,40,'#ff4960',24,240);floatText(e.x,e.y+70,'+150','#ff8a87')}}}player.lastHit++}
 for(const e of enemies){if(e.dead){e.dead-=dt;continue}e.phase+=dt*4;e.attackCd-=dt;e.attack=Math.max(0,e.attack-dt);e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.face=Math.sign(dx)||e.face;if(e.stun<=0){if(d>(e.kind==='boss'?105:64)){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*.5*dt}else if(e.attackCd<=0){e.attack=.35;e.attackCd=e.kind==='boss'?1.3:rand(1.3,2.1);if(e.kind==='boss'&&d>100)bolts.push({x:e.x,y:e.y,z:55,vx:dx/d*240,vy:dy/d*240,life:2,enemy:true});else setTimeout(()=>{},0)}}if(e.attack>0&&e.attack<.14&&d<(e.kind==='boss'?120:80)&&Math.abs(dy)<65&&player.inv<=0){player.hp-=e.kind==='boss'?19:10;player.inv=.75;player.stun=.18;shake=9;particle(player.x,player.y,50,'#fa3f51',13,210);floatText(player.x,player.y+75,'-'+(e.kind==='boss'?19:10),'#ff6572');stylePoints=Math.max(0,stylePoints-30)}}
 // enemy contact attacks have a single hit latch
 for(const e of enemies){if(e.attack===0)e.didHit=false}
 for(const b of bolts){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.enemy){if(Math.hypot(b.x-player.x,b.y-player.y)<34&&player.inv<=0){b.life=0;player.hp-=13;player.inv=.65;shake=7;particle(player.x,player.y,50,'#ff5265',12,190)}}else for(const e of enemies){if(!e.dead&&Math.hypot(b.x-e.x,b.y-e.y)<35){b.life=0;e.hp-=12;e.stun=.12;particle(e.x,e.y,50,'#8deaff',7,130);floatText(e.x,e.y+35,'-12','#a9efff');addStyle(12);if(e.hp<=0){e.dead=.45;kills++;score+=150;player.hp=Math.min(player.max,player.hp+5)}}}}
 bolts=bolts.filter(b=>b.life>0);particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vz-=260*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);slashes.forEach(s=>s.life-=dt);slashes=slashes.filter(s=>s.life>0);floaters.forEach(f=>{f.life-=dt;f.y+=35*dt});floaters=floaters.filter(f=>f.life>0);
 enemies=enemies.filter(e=>e.dead>0||e.hp>0);if(!enemies.some(e=>!e.dead)&&waveWait===0)waveWait=1.4;if(waveWait>0){waveWait-=dt;if(waveWait<=0){wave++;spawnWave();player.hp=Math.min(player.max,player.hp+14)}}comboTimer-=dt;if(comboTimer<=0){hitCount=0;ui.combo.classList.remove('show');if(stylePoints>0)stylePoints=Math.max(0,stylePoints-8*dt);else{ui.style.classList.remove('show');styleRank=0}}
 if(player.hp<=0){player.hp=0;finish(false)}ui.health.style.width=(player.hp/player.max*100)+'%';ui.score.textContent=String(score).padStart(6,'0');ui.bossHealth.style.width=((enemies.find(e=>e.kind==='boss')?.hp||0)/180*100)+'%';ui.meter.innerHTML=Array.from({length:5},(_,i)=>`<span class="pip ${i<Math.floor(player.hp/20)?'full':''}"></span>`).join('');}
function finish(win){if(gameOver)return;gameOver=true;active=false;ui.hud.style.display='none';ui.overlay.classList.remove('hide');ui.result.style.display='block';ui.resultText.innerHTML=win?'<b>LA GRIETA HA SIDO SELLADA.</b> Tu estilo quedará escrito en las cenizas.':'<b>LA OSCURIDAD TE RECLAMA.</b> Cada caída afila la hoja.';$('#start').style.display='none';ui.resultText.innerHTML+=`<br><span style="color:#e9bd7a">PUNTUACIÓN ${String(score).padStart(6,'0')} · SECTOR ${String(wave).padStart(2,'0')}</span>`;}

